cat > /tmp/probe.mjs <<'EOF'
import { createServer } from 'node:http'
const t0 = Date.now()
const log = (m) => console.log(`[+${String(Date.now()-t0).padStart(5)}ms] ${m}`)

// Fake analytics service, deliberately slow to respond.
const analytics = createServer((req, res) => {
  let body = ''
  req.on('data', (c) => (body += c))
  req.on('end', () => {
    log(`ANALYTICS received: ${body.slice(0, 200)}`)
    setTimeout(() => { res.writeHead(200); res.end('{}') }, 1500)
  })
})
await new Promise((r) => analytics.listen(9911, r))
log('analytics listener up on :9911')

// Wait for the Next server to be ready.
for (let i = 0; i < 60; i++) {
  try { await fetch('http://127.0.0.1:9910/'); break } catch { await new Promise(r=>setTimeout(r,500)) }
}

log('--- issuing page request ---')
const res = await fetch('http://127.0.0.1:9910/', {
  headers: { 'user-agent': 'probe-agent/1.0', referer: 'https://example.com/from' },
})
const html = await res.text()
log(`PAGE response fully received (status ${res.status}, ${html.length} bytes)`)
log(`welcome message present: ${/<h1>Welcome<\/h1>/.test(html)}`)

await new Promise((r) => setTimeout(r, 3000))
analytics.close()
EOF
